    private void chooseCategory(int index){
        if(index==category){if(!visible.isEmpty())focusGuide();return;}
        category=index;page=0;selected=null;
        if(readingCatalog&&all.isEmpty()){drawPage(false);return;}
        readingCatalog=false;
        filter(false);
        if(!visible.isEmpty())focusGuide();
    }
    private boolean focusCategory(){
        View target=category<categoryViews.size()?categoryViews.get(category):null;
        if(target!=null&&target.requestFocus())return true;
        for(View view:categoryViews)if(view!=null&&view.requestFocus())return true;
        return false;
    }
