    private void toggle(LiveTvData.Channel ch){int old=filtered.indexOf(ch);favourites.toggle(ch,all);Toast.makeText(getContext(),favourites.has(ch,all)?t("Added to favourites","Añadido a favoritos"):t("Removed from favourites","Quitado de favoritos"),Toast.LENGTH_SHORT).show();if(category==1){List<LiveTvData.Channel> remaining=new ArrayList<>();for(LiveTvData.Channel c:all)if(favourites.has(c,all))remaining.add(c);if(!remaining.contains(selected))selected=remaining.isEmpty()?null:remaining.get(Math.max(0,Math.min(old,remaining.size()-1)));filter(true);}else if(timeline!=null)timeline.favorites(stars());else drawPage(false);}
    private VelaProgrammeArt programmeArt;
    private void activateChannel(LiveTvData.Channel ch,LiveTvData.Programme p){long now=System.currentTimeMillis()/1000;if(p==null||p.current(now)){host.play(ch,all);return;}closeModal();VelaContentDetails card=new VelaContentDetails(getContext(),p.title,ch.name+" · "+time(p.start)+"–"+time(p.end)+" · "+(p.end<=now?L10n.text("Ended"):L10n.text("Upcoming")),p.description,-1);String artwork=VelaProgrammeArt.url(p.image.isEmpty()?ch.logo:p.image);card.broadcast(!artwork.isEmpty());modal=new FrameLayout(getContext());modal.setBackground(VelaContentDetails.programmeScrim());put(body,modal,0,0,1790,940);put(modal,card,200,120,1390,660);if(!artwork.isEmpty()){programmeArt=new VelaProgrammeArt(getContext(),modal);programmeArt.bind(card.image,artwork);}VelaAutoTune.action(card,getContext(),"antenna",LiteChannelPersonal.key(ch,all),ch.name,p);TextView watch=card.action(L10n.text("Watch live"),"",()->host.play(ch,all));card.action(VelaShows.follows(getContext(),p.title)?L10n.text("✓ Stop following"):L10n.text("+ Follow programme"),"",()->{VelaShows.toggle(getContext(),p.title);VelaShows.remember(getContext(),Arrays.asList(new VelaShows.Airing(p.title,ch.name,p.start,p.end,"",p.description,p.image,ch.logo)));activateChannel(ch,p);});VelaShows.Airing airing=new VelaShows.Airing(p.title,ch.name,p.start,p.end,"",p.description,p.image,ch.logo);card.action(VelaWatchlist.contains(getContext(),VelaWatchlist.airingId(airing))?L10n.text("Remove from Watch later"):L10n.text("Save for later"),"",()->{try{VelaWatchlist.toggle(getContext(),VelaWatchlist.airing(airing));activateChannel(ch,p);}catch(Exception error){Toast.makeText(getContext(),L10n.text("Could not save this item."),0).show();}});card.action(L10n.text("Back to guide"),"",this::closeModal);if(p.start>System.currentTimeMillis()/1000)card.actions.getChildAt(0).requestFocus();else watch.requestFocus();}
    private void organize(){
        if(loading||closed||organizer!=null)return;TvPersonalization personal=new TvPersonalization(getContext(),"antenna");LiveTvData.Channel current=selected;List<LiveTvData.Channel> catalogue=all;
        if(guideBackdrop!=null)guideBackdrop.show("");
        for(int i=0;i<body.getChildCount();i++){View view=body.getChildAt(i);organizerUnderlay.put(view,view.getVisibility());view.setVisibility(INVISIBLE);}modal=new FrameLayout(getContext());put(body,modal,0,0,1790,940);organizer=new TvChannelOrganizer(getContext(),new TvChannelOrganizer.Provider(){
            public List<TvPersonalization.Item> items(int tab){if(tab==1)return personal.hidden();List<TvPersonalization.Item> out=new ArrayList<>();if(tab==2){String[] labels={t("All channels","Todos los canales"),t("Favourites","Favoritos"),t("Television","Televisión"),t("Radio","Radio"),t("HD channels","Canales HD"),t("Recent","Recientes")};for(int i=1;i<labels.length;i++)out.add(new TvPersonalization.Item(""+i,labels[i],personal.groupHidden(""+i)));}else{List<LiveTvData.Channel> values=tab==3?LiteChannelPersonal.recent(getContext(),catalogue):LiteChannelPersonal.visible(getContext(),catalogue);for(LiveTvData.Channel c:values)if(tab==3||favourites.has(c,catalogue))out.add(new TvPersonalization.Item(LiteChannelPersonal.key(c,catalogue),c.name));if(tab==0)personal.sort(out);}return out;}
            public void activate(int tab,String key){if(tab==1){if(key.equals("@selected")){if(current!=null&&!personal.hide(LiteChannelPersonal.key(current,catalogue),current.name,true))throw new IllegalStateException();}else personal.hide(key,"",false);}else if(tab==2){if(!personal.hideGroup(key,key,!personal.groupHidden(key)))throw new IllegalStateException();}else if(tab==3)for(LiveTvData.Channel c:LiteChannelPersonal.recent(getContext(),catalogue))if(LiteChannelPersonal.key(c,catalogue).equals(key)){main.post(()->{closeModal();host.play(c,catalogue);});break;}}
            public String selectedLabel(){return current==null?"":current.name;}public void order(List<String> keys){personal.order(keys);}public void clearRecent(){personal.clearRecent();}public void close(){closeModal();filter(false);}
        });put(modal,organizer,0,0,1790,940);
    }
    boolean remote(KeyEvent e){if(e.getKeyCode()==KeyEvent.KEYCODE_MENU){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)organize();return true;}return false;}
    private void closeModal(){if(programmeArt!=null){programmeArt.close();programmeArt=null;}if(organizer!=null){organizer.close();organizer=null;for(Map.Entry<View,Integer> entry:organizerUnderlay.entrySet())if(entry.getKey().getParent()==body)entry.getKey().setVisibility(entry.getValue());organizerUnderlay.clear();}if(modal==null)return;body.removeView(modal);modal=null;if(selected!=null)updateDetail(selected,timeline==null?current(programmes,selected,System.currentTimeMillis()/1000):timeline.programme());focusGuide();}
    boolean back(){if(organizer!=null)return organizer.back();if(modal!=null){closeModal();return true;}return false;}
    public void close(){if(closed)return;if(programmeArt!=null){programmeArt.close();programmeArt=null;}VelaWorkspace.prefs(getContext(),"lite_tv").edit().putInt("category",category).apply();if(selected!=null)VelaWorkspace.prefs(getContext(),"lite_tv").edit().putString("selected",selected.identity).putString("selected_alias",selected.alias).apply();closed=true;cancel();main.removeCallbacksAndMessages(null);if(observing){getContext().getContentResolver().unregisterContentObserver(channelObserver);getContext().getContentResolver().unregisterContentObserver(programmeObserver);observing=false;}worker.shutdownNow();clearViews();
        if(guideBackdrop!=null&&guideBackdrop.getParent() instanceof FrameLayout)((FrameLayout)guideBackdrop.getParent()).removeView(guideBackdrop);
        logos.close();pageLogos.clear();programmes=Collections.emptyMap();all=filtered=visible=Collections.emptyList();body.removeAllViews();}
